    98	    masteryGain * weights.masteryGain +
    99	      retention * weights.retention +
   100	      engagement * weights.engagement +
   101	      transfer * weights.transfer -
   102	      confusion * weights.confusion,
   103	    0,
   104	    1
   105	  );
   106	
   107	  const explanations: string[] = [];
   108	  if (upRatio > 0.6) explanations.push("learner gave mostly positive feedback");
   109	  if (confusedRatio > 0.3) explanations.push("learner was frequently confused");
   110	  if (downRatio > 0.2) explanations.push("learner gave substantial negative feedback");
   111	  if (avgMastery > 0.7) explanations.push("mastery estimates are high");
   112	  if (avgMastery < 0.3) explanations.push("mastery estimates are low");
   113	  if (avgQuiz !== null) {
   114	    explanations.push(`graded quiz average is ${(avgQuiz * 100).toFixed(0)}% across ${quizScores.length} quiz(zes)`);
