   140	export function simulateDeterministicTeaching(
   141	  policy: TeacherPolicy,
   142	  topic: TopicDefinition,
   143	  learner: LearnerProfile,
   144	  weights: SimulationWeights
   145	): TeachingSimulation {
   146	  const intuitionFit = 1 - Math.abs(policy.analogyDensity - learner.analogyNeed);
   147	  const rigorTarget = clamp((topic.formalism + learner.abstractionComfort) / 2);
   148	  const rigorFit = 1 - Math.abs(policy.formalism - rigorTarget);
   149	  const dialogueFit = 1 - Math.abs(policy.socraticRatio - learner.dialoguePreference);
   150	  const diagramTarget = topic.visualizable ? learner.diagramAffinity : 0.2;
   151	  const diagramFit = 1 - Math.abs(policy.diagramBias - diagramTarget);
   152	  const practiceNeed = clamp(1 - learner.priorKnowledge + learner.anxiety * 0.2);
   153	  const practiceFit = 1 - Math.abs(policy.exerciseCount / 5 - practiceNeed);
   154	  const reflectionFit = 1 - Math.abs(policy.reflectionBias - learner.transferDesire);
   155	  const overload = clamp(
   156	    policy.formalism * 0.35 +
   157	      (policy.exerciseCount / 5) * 0.15 +
   158	      policy.challengeRate * 0.3 -
   159	      learner.persistence * 0.2 +
   160	      learner.anxiety * 0.25 -
   161	      learner.priorKnowledge * 0.15
   162	  );
   163	
   164	  const masteryGain = clamp(
   165	    0.14 +
   166	      intuitionFit * 0.18 +
   167	      rigorFit * 0.2 +
   168	      dialogueFit * 0.12 +
   169	      diagramFit * 0.09 +
   170	      practiceFit * 0.12 +
   171	      (1 - overload) * 0.18
   172	  );
   173	  const retention = clamp(masteryGain * (0.55 + policy.retrievalPractice * 0.45));
   174	  const engagement = clamp(
   175	    0.12 +
   176	      intuitionFit * 0.16 +
   177	      dialogueFit * 0.16 +
   178	      diagramFit * 0.1 +
   179	      reflectionFit * 0.14 +
   180	      (1 - overload) * 0.18
   181	  );
   182	  const transfer = clamp(
   183	    masteryGain * (0.55 + policy.interdisciplinaryBias * 0.25 + learner.transferDesire * 0.2)
   184	  );
   185	  const confusion = clamp(
   186	    0.04 +
   187	      overload * 0.55 +
   188	      Math.abs(policy.formalism - learner.abstractionComfort) * 0.18 +
   189	      Math.abs(policy.challengeRate - learner.persistence) * 0.12
   190	  );
   191	  const score = clamp(
   192	    masteryGain * weights.masteryGain +
   193	      retention * weights.retention +
   194	      engagement * weights.engagement +
   195	      transfer * weights.transfer -
   196	      confusion * weights.confusion,
   197	    0,
   198	    1
   199	  );
   200	
   201	  return {
   202	    learner,
   203	    topic,
   204	    masteryGain,
   205	    retention,
   206	    engagement,
   207	    transfer,
   208	    confusion,
   209	    score,
   210	    breakdown: {
   211	      intuitionFit,
   212	      rigorFit,
   213	      dialogueFit,
   214	      diagramFit,
   215	      practiceFit,
   216	      reflectionFit,
   217	      overload,
   218	    },
   219	    explanation: ["Deterministic algebraic baseline."],
   220	  };
   221	}
