    36	export function extractRealOutcomes(state: LearnerState): RealLearnerOutcome[] {
    37	  const outcomes: RealLearnerOutcome[] = [];
    38	
    39	  for (const fb of state.feedback) {
    40	    const topicSlug = resolveTopic(fb.topic).slug;
    41	    const covered = state.coveredTopics.find((ct) => ct.slug === topicSlug || ct.slug === fb.topic);
    42	    const session =
    43	      state.sessions.find((s) => s.topicsCovered.includes(topicSlug)) ?? null;
    44	
    45	    let sessionDurationMs: number | null = null;
    46	    if (session?.startedAt && session?.endedAt) {
    47	      sessionDurationMs =
    48	        new Date(session.endedAt).getTime() -
    49	        new Date(session.startedAt).getTime();
    50	    }
    51	
    52	    outcomes.push({
    53	      learnerId: state.profile.id,
    54	      topic: topicSlug,
    55	      feedbackSignal: fb.signal,
    56	      quizScore: null,
    57	      sessionDurationMs,
    58	      masteryEstimate: covered?.masteryEstimate ?? 0.5,
    59	      outcomeScore: feedbackToOutcomeScore(fb.signal),
    60	    });
    61	  }
    62	
    63	  for (const quizResult of state.quizResults ?? []) {
    64	    const topicSlug = resolveTopic(quizResult.topic).slug;
    65	    const covered = state.coveredTopics.find((ct) => ct.slug === topicSlug);
    66	    outcomes.push({
    67	      learnerId: state.profile.id,
    68	      topic: topicSlug,
    69	      feedbackSignal:
    70	        quizResult.score >= 0.75 ? "thumbs-up" : quizResult.score < 0.4 ? "thumbs-down" : "confused",
    71	      quizScore: quizResult.score,
    72	      sessionDurationMs: null,
    73	      masteryEstimate: covered?.masteryEstimate ?? quizResult.score,
    74	      outcomeScore: quizResult.score,
    75	    });
    76	  }
    77	
    78	  return outcomes;
    79	}
