    81	export async function extractHarnessOutcomes(cwd: string, state: LearnerState): Promise<RealLearnerOutcome[]> {
    82	  const outcomes = extractRealOutcomes(state);
    83	  const fallbackTopic =
    84	    state.coveredTopics.at(-1)?.slug ??
